"""Explicit post-result interpretation; never changes the preregistered protocol."""
import json
from pathlib import Path

BASE=Path(__file__).resolve().parent
def read(name): return json.loads((BASE/name).read_text())
def save(name,x): (BASE/name).write_text(json.dumps(x,ensure_ascii=False,indent=2,allow_nan=False)+'\n')

d=read('dimension-value.json')
d['concordance']['verdict']='PASS'
d['concordance']['interpretation']='All three categories occur: HIGH488/MEDIUM1317/LOW125. LOW identifies125 opposed-family observations, all TRANSITION; HIGH includes both favorable agreement and adverse/stress agreement. It adds a descriptive type of agreement, not direction, certainty, probability or predictive skill. MEDIUM dominance68.24% limits granularity; prospective user comprehension remains unmeasured.'
d['uncertainty']['verdict']='PASS'
d['uncertainty']['interpretation']='LOW794/MEDIUM367/HIGH769; only813/1930 observations follow the nominal inverse of concordance. All125 LOW-concordance observations have LOW uncertainty: conflicting families can still select one unambiguous regime. HIGH is conditional rule ambiguity, not market uncertainty or error probability. It changes28.41% of pairs; preserve qualitative context and assess presentation prospectively.'
d['value_scope']='PASS means demonstrated distinct descriptive information with existing evidence; it does not certify user benefit or predictive validity.'
save('dimension-value.json',d)

r=read('redundancy-analysis.json');r['status']='PASS'
r['pairs']['participation_vs_leadership'].update(classification='MODERATE_INCREMENTAL',reason='Breadth and relative group leadership encode different equity structure; removing either loses the selective branch.452/649 changed sessions include46/243 disjoint effects. This is structural contribution within the same equity family; independent economic utility remains unestablished.')
r['pairs']['volatility_level_vs_momentum'].update(classification='MODERATE_INCREMENTAL',reason='Fast moves occur below VIX20 on93 sessions, while VIX>=25 persists without fast momentum on248. Removing both momentum horizons removes12 contractual STRESS sessions and changes34 additional non-overlapping outcomes. These are distinct level/change semantics within one volatility family, not a new vote.')
r['pairs']['correlation_level_vs_deterioration'].update(classification='WEAK_INCREMENTAL',reason='Removing correlation deterioration changes32/1930 decisions; removing correlation level changes142, with no overlap in changed decisions. High correlation appears without high delta240 times and high delta below high correlation125 times. Deterioration is structurally distinct but has little direct adjudication effect; no evidence supports removal or a new independent family.')
ab=read('ablation.json')
classes={'positive_5':'MODERATE_INCREMENTAL','positive_21':'MODERATE_INCREMENTAL','leadership_gap':'MODERATE_INCREMENTAL','vix_level':'MODERATE_INCREMENTAL','jump_1':'WEAK_INCREMENTAL','jump_5':'WEAK_INCREMENTAL','vx_slope':'MODERATE_INCREMENTAL','correlation_level':'MODERATE_INCREMENTAL','correlation_deterioration':'WEAK_INCREMENTAL','participation':'MODERATE_INCREMENTAL','volatility_momentum':'MODERATE_INCREMENTAL'}
r['condition_assessment']={k:{'classification':v,'regimes_changed':ab['reduced'][k]['periods']['ALL']['regimes_changed'],'stress_not_retained':ab['reduced'][k]['periods']['ALL']['stress_state_not_retained'],'pillar_states_changed':ab['reduced'][k]['pillar_states_changed'],'economic_utility':'INDETERMINATE','action':'RETAIN_CANONICAL; no independent utility or safe-removal conclusion follows from structural contribution'} for k,v in classes.items()}
r['classifications_are_post_result_interpretation']=True
r['minimum_sufficient_engine']='C03 unchanged is the smallest currently justified complete product contract. No tested reduction establishes preservation of practically all valuable information because utility is not independently labelled. This is a conservative delivery decision, not proof of unique mathematical minimality.'
save('redundancy-analysis.json',r)

s=read('threshold-sensitivity.json')
s['interpretation']={'largest_observed_boundary':'k_broad +/-1 changes108/97 of1930 states (5.60%/5.03%); in already-seen F3_TEST41/31 of420 (9.76%/7.38%). This is the priority boundary for prospective adjudication of breadth, not automatic retuning.',
 'continuous_thresholds':'Each single +/-5% continuous perturbation changes at most48/1930 decisions (2.49%, v_watch lower). Low aggregate disagreement does not prove safety at rare events.',
 'zero_effect_does_not_mean_unreachable':'curve_flat upper, curve_adverse lower and rho_floor lower have zero historical regime effect for this perturbation. Branch activity, overlapping predicates and limited sample matter; canonical conditions remain intact.',
 'scale_caution':'One sector is12.5% of k_broad=8; integer and continuous perturbation elasticities are not directly comparable.',
 'decision':'NO_RECALIBRATION. No predefined external utility/noise labels justify selecting any tested setting; all26 results retained.'}
save('threshold-sensitivity.json',s)

b=read('benchmarks.json')
b['missing_robustness']={'evidence':'challengers.test.mjs: explicit missing/undefined/nonfinite and calendar-gap witnesses; no missing rows occur in the1930 eligible core baseline.',
 'B0':'Only actual archived observations; no interpolation.', 'B1':'Requires current finite VIX only; valid volatility namespace may exist while C03 is incomplete.',
 'B2':'Requires VIX and admissible participation before any stress override.', 'B3':'Requires both named lineage descriptors before STRESS override. Immediate means no temporal confirmation after input eligibility; not bypass of missing core evidence.',
 'B4':'No prior fill at first row, absent prior regime or non-adjacent session.', 'B5':'Unchanged public input contract and110 Sweeper adversarial checks.'}
b['conclusion']='B1 is smoother but supplies volatility only. B2 and B3 discard equity leadership/breadth distinctions; B3 retains all source maintenance. B4 simply delays481 canonical changes, including18 stress entries. None establishes preservation of the complete descriptive contract at lower cost. V1 cannot be ranked on missing historical evidence. Keep C03; do not claim statistically proven superiority.'
