def cost(candidate,gain,stability,source,dependency,state,rule,threshold,maintenance,failure,verdict):
 return {'candidate':candidate,'information_gain':gain,'stability_gain':stability,'new_data_source':source,'new_runtime_dependency':dependency,'new_state':state,'new_rule':rule,'new_threshold':threshold,'maintenance_obligation':maintenance,'new_failure_modes':failure,'verdict':verdict}
matrix=[
 cost('C03 unchanged','Retains full accepted equity/volatility evidence contract','Baseline observed24.94% turnover',False,False,False,False,False,'Existing source/calendars/version contracts','Existing explicit INCOMPLETE boundary','KEEP'),
 cost('B1 VIX only','Loses all equity structure; descriptive volatility only','13.17% turnover',False,False,False,'Simplified4 volatility labels','3 retained VIX boundaries','Lower acquisition cost','CALM_VOL could be misread as broad equity participation','BENCHMARK_ONLY'),
 cost('B2 VIX+breadth','Loses leadership/fragility/curve and selective reachability','21.31% turnover',False,False,False,'Coarse4-state adjudication','Retained levels/counts','Two existing provider families','Breadth alone can mask defensive leadership or curve stress','BENCHMARK_ONLY'),
 cost('B3 family vote','Collapses useful internal risk-on structure','14.77% turnover',False,False,False,'4 final rules','Retains all core thresholds','No upstream reduction','Same acquisition cost with coarser meaning','BENCHMARK_ONLY'),
 cost('B4 previous state','No new information; delays current evidence','24.95% turnover on1928 pairs',False,False,'One prior-state memory','Lag current output',False,'Canonical plus memory lifecycle','Stress delay and stale display','REJECT_FOR_PRODUCT'),
 cost('11 reduced engines','Documented lost conditions; utility loss unlabelled','See all/year/F3 in ablation.json',False,False,False,'Explicit condition removal','No new threshold','Separate methodology versions and golden fixtures','Silent change in regime meaning if promoted','CHALLENGER_ONLY'),
 cost('26 threshold perturbations','No new information source','Variable; no selection target',False,False,False,False,'One altered existing parameter each','Calibration governance','Overfitting already-seen history','SENSITIVITY_ONLY'),
 cost('H1 confirmation','No new evidence;138 episodes withheld','12.13% turnover,356 contradicted holds',False,False,'Held state + pending candidate','One additional non-stress confirmation','Confirmation length2 observations','State reset, calendar/version/missing lifecycle','Delayed legitimate changes;77 stale risk-on sessions; prolonged stress exits','CHALLENGER_ONLY'),
 cost('P1 observed persistence','Adds descriptive observed age and named recovery duration','Does not alter transitions',False,False,'Diagnostic counters only','No adjudication rule',False,'Censoring and prospective reset semantics if later promoted','Users may misread long duration as confidence; batch output not live-ready','DIAGNOSTIC_ONLY'),
 cost('Cross-asset credit/rates/USD/commodities','Plausible distinct economics; no admitted paired PIT evidence','Not established','Would need admitted source/vintage contract','No selected package','No proposed taxonomy','Would require methodology proposal','Not selected','Licensing, calendars, revisions, adjusted-price basis','Credit ETF duration contamination; USD quote ambiguity; retrospective revisions','PARK_RESEARCH_ONLY'),
 cost('PFL component diagnostic','Portfolio topology within same equity family; no independent family','96 cluster-count changes; not a regime filter',False,'Existing PFL code if promoted','Diagnostic only','No canonical proposal','Existing PFL clustering/window assumptions','Portfolio weights/universe/252-return provenance','Portfolio-specific component could be mistaken for market state','RESEARCH_ONLY'),
 cost('BTC/GLD retained satellites','Native contextual flows; limited25/20 rows','Not a stability rule',False,False,False,False,False,'Existing optional-source calendar/unit contracts','Missing fund cells, GLD flow proxy and warmup; narrative utility unmeasured','KEEP_CONTEXTUAL_ONLY'),
 cost('Concordance/uncertainty/data-quality retained','Distinct agreement, rule ambiguity and evidence eligibility','No smoothing claim',False,False,False,False,False,'Existing dimension definitions','Ordinal names mistaken for probability or future risk','KEEP')]
save('complexity-matrix.json',{'scope':'Post-result qualitative accounting; no fabricated benefit decimals','canonical_changes':0,'matrix':matrix,'minimum_sufficient_engine':r['minimum_sufficient_engine']})

